#[derive(Debug)]
pub enum LinAlgError {
    NonConvergence(String),
    SingularMatrix(String),
    NonSquareMatrix(String),
    IncompatibleDimensions(String),
    InvalidInput(String),
    NumericalInstability(String),
    Other(String),
}

fn select_error(error_variant: u8, message: String) -> LinAlgError {
    match error_variant {
        0 => LinAlgError::NonConvergence(message),
        1 => LinAlgError::SingularMatrix(message),
        2 => LinAlgError::NonSquareMatrix(message),
        3 => LinAlgError::IncompatibleDimensions(message),
        4 => LinAlgError::InvalidInput(message),
        5 => LinAlgError::NumericalInstability(message),
        _ => LinAlgError::Other(message),
    }
}

fn check_lin_alg_error(condition: bool, error_variant: u8, message: String) -> Option<LinAlgError> {
    if condition {
        Some(select_error(error_variant, message))
    } else {
        None
    }
}

// Example usage
fn main() {
    let error = check_lin_alg_error(true, 1, "Matrix is singular".to_string());
    println!("{:?}", error); // Output: Some(SingularMatrix("Matrix is singular"))
    
    let no_error = check_lin_alg_error(false, 2, "This message won't be used".to_string());
    println!("{:?}", no_error); // Output: None
}